 259→// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
 260→function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
 261→  if (!rawCss) return "";
 262→  const css = rawCss.replace(/<\/style>/gi, "");
 263→  let result = "";
 264→  let remaining = css;
 265→  while (remaining.length > 0) {
 266→    const openBrace = remaining.indexOf("{");
 267→    if (openBrace === -1) break;
 268→    const closeBrace = remaining.indexOf("}", openBrace);
 269→    if (closeBrace === -1) break;
 270→    const selector = remaining.substring(0, openBrace).trim();
 271→    const body = remaining.substring(openBrace + 1, closeBrace);
 272→    remaining = remaining.substring(closeBrace + 1);
 273→    if (selector.startsWith("@")) {
 274→      result += selector + "{" + body + "}";
 275→    } else if (selector) {
 276→      const prefixed = selector.split(",").map(s => {
 277→        s = s.trim();
 278→        return s ? "#" + wid + " " + s : "";
 279→      }).filter(Boolean).join(", ");
 280→      result += prefixed + " {" + body + "}";
 281→    }
 282→  }
 283→  return result;
 284→}
