 593→// ── Reusable position tile selector ─────────────────────────────────────────
 594→const PositionTile = memo(function PositionTile({
 595→  value,
 596→  label,
 597→  selected,
 598→  disabled,
 599→  onSelect,
 600→  children,
 601→}: {
 602→  value: string;
 603→  label: string;
 604→  selected: boolean;
 605→  disabled: boolean;
 606→  onSelect: (v: string) => void;
 607→  children: React.ReactNode;
 608→}) {
 609→  return (
 610→    <div
 611→      role="button"
 612→      tabIndex={0}
 613→      aria-pressed={selected}
 614→      onClick={() => !disabled && onSelect(value)}
 615→      onKeyDown={(e) => {
 616→        if ((e.key === "Enter" || e.key === " ") && !disabled) {
 617→          e.preventDefault();
 618→          onSelect(value);
 619→        }
 620→      }}
 621→      style={{
 622→        flex: 1,
 623→        minWidth: 100,
 624→        border: selected
 625→          ? "2px solid var(--p-color-border-emphasis)"
 626→          : "2px solid var(--p-color-border-secondary)",
 627→        borderRadius: 10,
 628→        padding: "12px 10px",
 629→        cursor: disabled ? "not-allowed" : "pointer",
 630→        background: selected
 631→          ? "var(--p-color-bg-surface-selected)"
 632→          : "var(--p-color-bg-surface)",
 633→        textAlign: "center" as const,
 634→        opacity: disabled ? 0.5 : 1,
 635→        transition: "border-color 0.15s ease, background 0.15s ease",
 636→        outline: "none",
 637→      }}
 638→    >
 639→      <BlockStack gap="100" inlineAlign="center">
 640→        {children}
 641→        <Text as="p" variant="bodySm" fontWeight={selected ? "semibold" : "regular"}>
 642→          {label}
 643→        </Text>
 644→      </BlockStack>
 645→    </div>
 646→  );
 647→});
