              }}
            >
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{width:18,height:18}}>
                <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/>
              </svg>
              Check Delivery
            </button>
          </div>
        </div>
      </>
    );
  }

  // Popup position: show trigger button + hint of overlay
  if (cfg.position === "popup") {
    return (
      <>
        {/* eslint-disable-next-line react/no-danger */}
        <style dangerouslySetInnerHTML={{ __html: css }} />
        <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
          <Text as="p" variant="bodySm" tone="subdued">
            A trigger button will appear in the section. Clicking it opens a centered popup.
          </Text>
          <div>
            <button
              type="button"
              style={{
                background: cfg.primaryColor,
                color: "#fff",
                border: "none",
                borderRadius: cfg.borderRadius + "px",
                padding: "12px 28px",
                fontSize: "14px",
                fontWeight: 600,
                cursor: "pointer",
                display: "inline-flex",
                alignItems: "center",
                gap: "8px",
              }}
            >
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{width:16,height:16}}>
                <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/>
              </svg>
              {cfg.heading}
            </button>
          </div>
          <div
            style={{
              background: "rgba(0,0,0,.06)",
              borderRadius: "8px",
              padding: "12px",
              border: "2px dashed #c9cccf",
            }}
          >
            <Text as="p" variant="bodySm" tone="subdued">
              Popup content preview:
            </Text>
            <div style={{ marginTop: "8px" }}>{widgetHtml}</div>
          </div>
        </div>
      </>
    );
  }

  // Inline (default)
  return (
    <>
      {/* eslint-disable-next-line react/no-danger */}
      <style dangerouslySetInnerHTML={{ __html: css }} />
      {widgetHtml}
    </>
  );
});

// ── Reusable position tile selector ─────────────────────────────────────────
const PositionTile = memo(function PositionTile({
  value,
  label,
  selected,
  disabled,
  onSelect,
  children,
}: {
  value: string;
  label: string;
  selected: boolean;
  disabled: boolean;
  onSelect: (v: string) => void;
  children: React.ReactNode;
}) {
  return (
    <div
      role="button"
      tabIndex={0}
      aria-pressed={selected}
      onClick={() => !disabled && onSelect(value)}
      onKeyDown={(e) => {
        if ((e.key === "Enter" || e.key === " ") && !disabled) {
          e.preventDefault();
          onSelect(value);
        }
      }}
      style={{
        flex: 1,
        minWidth: 100,
        border: selected
          ? "2px solid var(--p-color-border-emphasis)"
          : "2px solid var(--p-color-border-secondary)",
        borderRadius: 10,
        padding: "12px 10px",
        cursor: disabled ? "not-allowed" : "pointer",
        background: selected
          ? "var(--p-color-bg-surface-selected)"
          : "var(--p-color-bg-surface)",
        textAlign: "center" as const,
        opacity: disabled ? 0.5 : 1,
        transition: "border-color 0.15s ease, background 0.15s ease",
        outline: "none",
      }}
    >
      <BlockStack gap="100" inlineAlign="center">
        {children}
        <Text as="p" variant="bodySm" fontWeight={selected ? "semibold" : "regular"}>
          {label}
        </Text>
      </BlockStack>
    </div>
  );
});

