    W + " .zcc-btn:hover{filter:brightness(1.08)}" +
    W + " .zcc-btn:active{filter:brightness(0.95)}" +
    W + " .zcc-btn:disabled{opacity:.6;cursor:not-allowed;filter:none}" +
