    >
      <Box paddingBlockEnd="1600">
        <Layout>

          {/* Settings + Preview */}
          <Layout.Section>
            <InlineGrid columns={{ xs: 1, md: 2 }} gap="400" alignItems="start">
              {/* ── Settings Column ── */}
              <BlockStack gap="400">

                {/* Layout — Position Only */}
                <Card>
